def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Compare rows for repeated horizontal patterns. Where one row contains
    # a strict subset of another row's same-colored pattern, mark its gaps.
    for i in range(h):
        for j in range(i + 1, h):
            for color in set(grid[i]) | set(grid[j]):
                if color == bg:
                    continue
                si = {c for c in range(w) if grid[i][c] == color}
                sj = {c for c in range(w) if grid[j][c] == color}
                if len(si) < 3 or len(sj) < 3:
                    continue

                if si < sj:
                    target, smaller, larger = i, si, sj
                elif sj < si:
                    target, smaller, larger = j, sj, si
                else:
                    continue

                missing = larger - smaller
                if all(grid[target][c] == bg for c in missing):
                    for c in missing:
                        out[target][c] = 1

    return out
